<?php
require_once __DIR__.'/functions.php';$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';
 if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6)$errors[]='Please provide a valid name, email and a password of at least 6 characters.';
 else try{$check=$pdo->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$check->execute([$email]);if($check->fetch())$errors[]='Email is already registered.';else{$pdo->beginTransaction();$pdo->prepare("INSERT INTO users(name,email,phone,password,role) VALUES(?,?,?,?, 'buyer')")->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO clients(user_id,address) VALUES(?,?)")->execute([$uid,'']);$pdo->commit();$sent=send_registration_email($name,$email,'buyer');flash('success',$sent?'Account created. A welcome email has been sent.':'Account created successfully. Please login.');redirect('login.php');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Could not create the account. Please try again.';error_log('AZARO registration: '.$e->getMessage());}}
$title='Create Account';include __DIR__.'/partials/header.php';?>
<section class="page"><div class="panel auth"><div class="eyebrow">JOIN AZARO</div><h1>Create your account</h1><p class="muted">Create a buyer account and start shopping from AZARO.</p><?php foreach($errors as $x):?><div class="flash error" style="position:static;margin:8px 0"><?=e($x)?></div><?php endforeach;?><form method="post" class="form-grid"><?=csrf_field()?><div class="field full"><label>Full name</label><input name="name" value="<?=e($_POST['name']??'')?>" required></div><div class="field"><label>Email</label><input name="email" type="email" value="<?=e($_POST['email']??'')?>" required></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($_POST['phone']??'')?>"></div><div class="field full"><label>Password</label><input name="password" type="password" minlength="6" required></div><div class="field full"><button class="btn btn-primary">Create Buyer Account</button></div></form><p>Already have an account? <a href="<?=BASE_URL?>/login.php" style="color:var(--blue)">Login</a></p></div></section><?php include __DIR__.'/partials/footer.php';?>
